}

iframe.youtube {
  width: 100%;
  margin-bottom: 15px;
}

@media screen and (max-width: 350px) {
  iframe.youtube {
    height: 200px;
  }
}

@media screen and (min-width: 350px) {
  iframe.youtube {
    height: 300px;
  }
}

@media screen and (min-width: 600px) {
  iframe.youtube {
    height: 400px;
  }
}

.winstore {
  width: 200px;
  border-radius: 8px;
  margin-top: 25px;
}

[data-theme="dark"] .withings {
  background: white;
  padding: 17px 10px 10px 10px;
  display: inline;
  border-radius: 10px;
}

[data-theme="light"] .withings {
  background: black;
  padding: 17px 10px 10px 10px;
  display: inline;
  border-radius: 10px;
}

.withings svg {
  width: 150px;
}

[data-theme="light"] .withings svg path {
  fill: white;
}

[data-theme="dark"] .withings svg path {
  fill: black;
}

/* Fonts */

@font-face {
  font-family: "Victor Mono";
  src: url('/fonts/VictorMono.ttf') format("truetype");
  font-display: swap;
}

:root {
  --ifm-font-family-monospace: "Victor Mono", "Symbols Nerd Font Mono",
    "Symbols Nerd Font", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --ifm-font-family-base: "Inter";
  --ifm-heading-font-weight: 600;
}

h1,
h2,
h3 {
  letter-spacing: -0.02em;
  line-height: 1.2;
}

h1,
h2 {
  text-wrap: balance;
}

code {
  font-family: var(--ifm-font-family-monospace);
  font-variant-ligatures: none;
  font-feature-settings: "liga" 0, "calt" 0;
}

code[class*="language-"],
pre[class*="language-"] {
  font-family: var(--ifm-font-family-monospace);
  font-variant-ligatures: none;
  font-feature-settings: "liga" 0, "calt" 0;
}

table {
  /* We need this to be able to use border-radius. */
  border-collapse: separate;

  /* Add a 1px border spacing for out box-shadow to fit into. Increase this if you want to increase the border width. */
  border-spacing: 1px;
}

table th,
table td {
  /* Remove any borders from our stylesheet. */
  border: 0;

