/* Fonts */

@font-face {
  font-family: "Victor Mono";
  src: url('/fonts/VictorMono.ttf') format("truetype");
  font-display: swap;
}

:root {
  --ifm-font-family-monospace: "Victor Mono", "Symbols Nerd Font Mono",
    "Symbols Nerd Font", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --ifm-font-family-base: "Inter";
  --ifm-heading-font-weight: 600;
  --ifm-heading-line-height: 1.2;
}

h1,
h2,
h3 {
  letter-spacing: -0.02em;
}

h1,
h2 {
  text-wrap: balance;
}

code {
  font-family: var(--ifm-font-family-monospace);
  font-variant-ligatures: none;
  font-feature-settings: "liga" 0, "calt" 0;
}

code[class*="language-"],
pre[class*="language-"] {
  font-family: var(--ifm-font-family-monospace);
  font-variant-ligatures: none;
  font-feature-settings: "liga" 0, "calt" 0;
}

table {
  /* We need this to be able to use border-radius. */
  border-collapse: separate;

  /* Add a 1px border spacing for out box-shadow to fit into. Increase this if you want to increase the border width. */
  border-spacing: 1px;
}

table th,
table td {
  /* Remove any borders from our stylesheet. */
  border: 0;

  /* Use the spread value on the box-shadow to set the border width. */
  box-shadow: 0 0 0 1px var(--ifm-table-border-color);
}

table th:first-child {
  border-top-left-radius: 6.4px;
}

table th:last-child {
  border-top-right-radius: 6.4px;
}

table tr:last-child td:first-child {
  border-bottom-left-radius: 6.4px;
}

table tr:last-child td:last-child {
  border-bottom-right-radius: 6.4px;
}

