file.content:
/* stylelint-disable docusaurus/copyright-header */

/**
 * CSS files with the .module.css suffix will be treated as CSS modules
 * and scoped locally.
 */

.heroBanner {
  padding: 5rem 0 4rem;
  text-align: center;
  position: relative;
  overflow: hidden;
}

@media screen and (max-width: 966px) {
  .heroBanner {
    padding: 3rem 0 2rem;
  }
}

.heroBanner :global(.container) {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}

.heroBanner :global(.container) > * {
  margin: 0;
}

.subtitle {
  max-width: 640px;
}

.installBox {
  width: 100%;
  max-width: 560px;
  text-align: left;
}

.installNote {
  margin-top: 0.75rem;
  font-size: 0.875rem;
  text-align: center;
}

.buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem 1.5rem;
  align-items: center;
  justify-content: center;
}

.heroImage {
  max-width: 100%;
  height: auto;
}

.features {
  display: flex;
  align-items: center;
  padding: 2rem 0;
  width: 100%;
}

.shellRow {
  padding: 0 0 3rem;
  text-align: center;
}

.shellList {
  color: var(--ifm-color-emphasis-700);
  font-size: 0.9rem;
}

