import json
import os
import re
import sys

EMAIL = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
ABSPATH = re.compile(r"(?:[A-Za-z]:[\\/]|\\\\|/home/|/Users/)")
USER = re.compile(r"(?<![A-Za-z])jande(?![A-Za-z])", re.IGNORECASE)
HOST = re.compile(r"(?<![A-Za-z])surface-pro(?![A-Za-z])", re.IGNORECASE)
ALLOWED_EMAIL = {"alice@contoso.com"}

findings = []


def check(value, where):
    for m in EMAIL.finditer(value):
        if m.group(0) not in ALLOWED_EMAIL:
            findings.append(("email", where, m.group(0)))
    if ABSPATH.search(value):
        findings.append(("abspath", where, value[:70]))
    if USER.search(value):
        findings.append(("username", where, value[:70]))
    if HOST.search(value):
        findings.append(("hostname", where, value[:70]))


def walk(node, path):
    if isinstance(node, dict):
        for k, v in node.items():
            walk(v, f"{path}.{k}")
    elif isinstance(node, list):
        for i, v in enumerate(node):
            walk(v, f"{path}[{i}]")
    elif isinstance(node, str):
        check(node, path)


root = sys.argv[1]

fixtures = glob.glob(os.path.join(root, "src/prompt/testdata/fixtures/*.data.json"))
for p in fixtures:
    walk(json.load(open(p, encoding="utf-8")), os.path.basename(p))

# Goldens are raw ANSI bytes, not JSON - scan them as text.
goldens = glob.glob(os.path.join(root, "src/prompt/testdata/goldens/*.golden"))
goldens.append(os.path.join(root, "src/prompt/testdata/goldens/manifest.txt"))
for p in goldens:
    check(open(p, encoding="utf-8", errors="replace").read(), os.path.basename(p))

print(f"scanned {len(fixtures)} fixtures + {len(goldens)} golden/manifest files")
if not findings:
    print("CLEAN - no email, absolute path, username or hostname found")
else:
    print(f"{len(findings)} FINDINGS:")
    for kind, where, val in findings[:20]:
        print(f"  {kind:9} {where}  ->  {val}")

